#define main source_original_main
#include "../aop-cuda/main.cu"
#undef main
#include <vector>
#include <fstream>
#include <stdexcept>
#include "study_cases.h"
const int G=16;const double GUARD=-987654321.25,POISON=-1234567.25;
std::vector<double>readf(const char*n){std::ifstream f(n,std::ios::binary|std::ios::ate);if(!f)throw std::runtime_error("fixturemissing");size_t bytes=f.tellg();if(bytes%8)throw std::runtime_error("fixturetype");f.seekg(0);std::vector<double>v(bytes/8);if(!f.read((char*)v.data(),bytes))throw std::runtime_error("shortfixture");return v;}
struct State{Case c;std::vector<double>h[4];double*d[4];int*flag;std::vector<int>hf;double price;State(Case q,std::vector<double>&f):c(q){int sizes[]={q.n*q.steps,q.n*q.steps,16*q.steps,8192};for(int k=0;k<4;k++){h[k].assign(sizes[k]+2*G,GUARD);std::fill(h[k].begin()+G,h[k].end()-G,POISON);if(k==0)std::copy(f.begin()+q.io,f.begin()+q.io+sizes[0],h[k].begin()+G);CHECK_CUDA(cudaMalloc(&d[k],h[k].size()*8));CHECK_CUDA(cudaMemcpy(d[k],h[k].data(),h[k].size()*8,cudaMemcpyHostToDevice));}hf.assign(q.steps+2*G,-55555);CHECK_CUDA(cudaMalloc(&flag,hf.size()*4));CHECK_CUDA(cudaMemcpy(flag,hf.data(),hf.size()*4,cudaMemcpyHostToDevice));}void reset(){for(int k=1;k<4;k++)CHECK_CUDA(cudaMemcpy(d[k],h[k].data(),h[k].size()*8,cudaMemcpyHostToDevice));CHECK_CUDA(cudaMemcpy(flag,hf.data(),hf.size()*4,cudaMemcpyHostToDevice));CHECK_CUDA(cudaDeviceSynchronize());}void run(){auto q=c;if(q.put)do_run(h[0].data()+G,q.steps,q.n,PayoffPut(q.K),q.dt,q.S0,q.r,q.sigma,d[0]+G,d[1]+G,d[1]+G+(q.steps-1)*q.n,d[2]+G,flag+G,d[3]+G,&price);else do_run(h[0].data()+G,q.steps,q.n,PayoffCall(q.K),q.dt,q.S0,q.r,q.sigma,d[0]+G,d[1]+G,d[1]+G+(q.steps-1)*q.n,d[2]+G,flag+G,d[3]+G,&price);}};
void capture(State&s,std::vector<double>&v){for(int k=0;k<4;k++){auto h=s.h[k];CHECK_CUDA(cudaMemcpy(h.data(),s.d[k],h.size()*8,cudaMemcpyDeviceToHost));v.insert(v.end(),h.begin(),h.end());}auto h=s.hf;CHECK_CUDA(cudaMemcpy(h.data(),s.flag,h.size()*4,cudaMemcpyDeviceToHost));for(int x:h)v.push_back(double(x));}
bool check(State&s,std::vector<double>&o,double&err){bool ok=true;for(int k=0;k<4;k++){auto h=s.h[k];CHECK_CUDA(cudaMemcpy(h.data(),s.d[k],h.size()*8,cudaMemcpyDeviceToHost));for(size_t i=0;i<h.size();i++){if(i<G||i>=h.size()-G)ok&=h[i]==GUARD;else if(k==0)ok&=h[i]==s.h[k][i];else if(k==1){double want=o[s.c.oo+i-G];err=std::max(err,std::abs(h[i]-want));if(std::abs(h[i]-want)>2e-6+1e-5*std::abs(want)){printf("PATH_ORACLE case_n=%d index=%zu actual=%.17g want=%.17g\n",s.c.n,i-G,h[i],want);ok=false;break;}}else ok&=std::isfinite(h[i]);}}auto h=s.hf;CHECK_CUDA(cudaMemcpy(h.data(),s.flag,h.size()*4,cudaMemcpyDeviceToHost));for(int i=0;i<int(h.size());i++)if(i<G||i>=int(h.size())-G)ok&=h[i]==-55555;else ok&=h[i]==0||h[i]==1;return ok;}
int main(){auto f=readf("input_f64.bin"),o=readf("oracle_paths_f64.bin");std::vector<State*>states;for(auto c:cases){auto*s=new State(c,f);s->run();double err=0;bool ok=check(*s,o,err);printf("WARM n=%d steps=%d price=%.17g maxoracleerr=%.17g pass=%d\n",c.n,c.steps,s->price,err,int(ok));fflush(stdout);if(!ok)throw std::runtime_error("independent_path_cashflow_oracle");states.push_back(s);}for(int trial=1;trial<=5;trial++){std::vector<double>pre,post,times,prices;bool ok=true;double seconds=0,err=0;for(auto*s:states){s->reset();capture(*s,pre);auto t=std::chrono::steady_clock::now();s->run();double sec=std::chrono::duration<double>(std::chrono::steady_clock::now()-t).count();seconds+=sec;times.push_back(sec);prices.push_back(s->price);ok&=check(*s,o,err);capture(*s,post);}size_t prefix=pre.size();pre.insert(pre.end(),post.begin(),post.end());std::string path="aop_trial"+std::to_string(trial)+".bin";std::ofstream file(path,std::ios::binary);if(!file.write((char*)pre.data(),pre.size()*8))throw std::runtime_error("artifactwrite");file.close();printf("STUDY_TRIAL {\"trial\":%d,\"correct\":%s,\"jit_excluded\":true,\"time_seconds\":%.12g,\"timing_region\":\"sum_seven_source_do_run_sample_H2D_through_scalar_D2H\",\"max_abs_error\":%.17g,\"max_rel_error\":null,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"shape\":[%zu],\"byte_order\":\"little\"},\"case_times_seconds\":[",trial,ok?"true":"false",seconds,err,path.c_str(),pre.size(),pre.size());for(size_t i=0;i<times.size();i++)printf("%s%.12g",i?",":"",times[i]);printf("],\"prices\":[");for(size_t i=0;i<prices.size();i++)printf("%s%.17g",i?",":"",prices[i]);printf("]}\n");fflush(stdout);}}
